'use strict';

const fs = require('fs');
const path = require('path');

const README_PATH = path.join(__dirname, 'README.md');
const OUTPUT_PATH = path.join(__dirname, 'results', 'status.json');
const DEFAULT_ENDPOINT = 'http://127.0.0.1:61824/status';
const EXPECTED_STATUS = 200;
const MAX_ATTEMPTS = 5;
const RETRY_DELAY_MS = 300;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function readEndpoint() {
  try {
    const readme = fs.readFileSync(README_PATH, 'utf8');
    const match = readme.match(/https?:\/\/\S+/);
    if (match) {
      return match[0].replace(/[.,;]+$/, '');
    }
  } catch (err) {
    if (err.code !== 'ENOENT') {
      throw err;
    }
  }
  return DEFAULT_ENDPOINT;
}

async function requestStatus(endpoint) {
  let lastError;

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
    try {
      const response = await fetch(endpoint, { headers: { accept: 'application/json' } });
      const body = await response.text();

      if (response.status !== EXPECTED_STATUS) {
        throw new Error(`HTTP ${response.status} from ${endpoint}: ${body}`);
      }

      let payload;
      try {
        payload = JSON.parse(body);
      } catch {
        throw new Error(`Response from ${endpoint} is not valid JSON: ${body}`);
      }

      if (!payload || typeof payload !== 'object' || payload.status !== EXPECTED_STATUS) {
        throw new Error(`Expected status=${EXPECTED_STATUS} from ${endpoint}, received ${body}`);
      }

      return payload.status;
    } catch (err) {
      lastError = err;
      if (attempt < MAX_ATTEMPTS) {
        await sleep(RETRY_DELAY_MS * attempt);
      }
    }
  }

  throw lastError;
}

async function main() {
  const endpoint = process.env.STATUS_ENDPOINT || readEndpoint();
  const status = await requestStatus(endpoint);

  fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
  fs.writeFileSync(OUTPUT_PATH, JSON.stringify({ status }), 'utf8');

  console.log(`GET ${endpoint} -> status=${status}`);
  console.log(`Wrote ${path.relative(__dirname, OUTPUT_PATH)}`);
}

main().catch((err) => {
  console.error(`client failed: ${err.message}`);
  process.exit(1);
});

