  const entry = process.argv[1];
  const resolved = entry ? path.resolve(entry) : path.resolve(process.cwd(), 'verify.js');
  return path.dirname(resolved);
}

const checks = [];

function check(name, fn) {
  checks.push({ name, fn });
}

async function main() {
  const fs = await import('node:fs');
  const path = await import('node:path');

  const baseDir = scriptDir(path);
  const outputPath = path.join(baseDir, 'results', 'status.json');

  check('results/status.json exists', () => {
    if (!fs.existsSync(outputPath)) {
      throw new Error(`missing file: ${path.relative(baseDir, outputPath)} (run: node client.js)`);
    }
  });

  check('results/status.json is valid JSON', () => {
    const raw = fs.readFileSync(outputPath, 'utf8');
    try {
      JSON.parse(raw);
    } catch (err) {
      throw new Error(`invalid JSON in ${path.relative(baseDir, outputPath)}: ${err.message}`);
    }
  });

